     7	/** Comprovante de reserva (e segunda via). */
     8	public record Receipt(String title, long reservationId, String guestName, String guestCpf, int roomNumber,
     9	                      RoomType roomType, LocalDate checkIn, LocalDate checkOut, int nights,
    10	                      BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    11	
    12	    public static final String TITLE = "Comprovante de reserva";
    13	    private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    14	
    15	    public static Receipt of(Reservation r, Room room) {
    16	        return new Receipt(TITLE, r.id(), r.guestName(), r.guestCpf(), room.number(), room.type(),
    17	                r.checkIn(), r.checkOut(), r.nights(), r.subtotal(), r.discount(), r.total());
    18	    }
    19	
    20	    public String text() {
    21	        StringBuilder sb = new StringBuilder();
    22	        sb.append(title).append(" nº ").append(reservationId).append('\n');
    23	        sb.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
    24	        sb.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
    25	        sb.append("Entrada: ").append(DATE.format(checkIn)).append(" | Saída: ").append(DATE.format(checkOut))
    26	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
    27	        sb.append("Diárias: ").append(Money.brl(subtotal)).append('\n');
    28	        if (discount.signum() > 0) {
    29	            sb.append("Desconto: ").append(Money.brl(discount)).append('\n');
    30	        }
    31	        sb.append("Total: ").append(Money.brl(total));
    32	        return sb.toString();
    33	    }
    34	}
