     7	
     8	public class Reservation {
     9	    private Long id;
    10	    private final int roomNumber;
    11	    private final String guestName;
    12	    private final String guestEmail;
    13	    private final String guestCpf;
    14	    private final LocalDate checkIn;
    15	    private final LocalDate checkOut;
    16	    private final int guests;
    17	    private final RatePlan ratePlan;
    18	    private final int nights;
    19	    private final BigDecimal subtotal;
    20	    private final BigDecimal discount;
    21	    private final BigDecimal total;
    22	    private ReservationStatus status;
    23	    private BigDecimal amountPaid;
    24	    private BigDecimal refund;
    25	
    26	    public Reservation(Long id, int roomNumber, String guestName, String guestEmail, String guestCpf,
    27	                       LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan,
    28	                       int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total,
    29	                       ReservationStatus status, BigDecimal amountPaid, BigDecimal refund) {
    30	        this.id = id;
    31	        this.roomNumber = roomNumber;
    32	        this.guestName = guestName;
    33	        this.guestEmail = guestEmail;
    34	        this.guestCpf = guestCpf;
    35	        this.checkIn = checkIn;
    36	        this.checkOut = checkOut;
    37	        this.guests = guests;
    38	        this.ratePlan = ratePlan;
    39	        this.nights = nights;
    40	        this.subtotal = subtotal;
    41	        this.discount = discount;
    42	        this.total = total;
    43	        this.status = status;
    44	        this.amountPaid = amountPaid;
    45	        this.refund = refund;
    46	    }
    47	
    48	    /** Nova reserva pendente, com os valores já calculados. */
    49	    public static Reservation book(Room room, String guestName, String guestEmail, String guestCpf,
    50	                                   LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    51	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    52	        BigDecimal subtotal = Stream.iterate(checkIn, d -> d.plusDays(1))
    53	                .limit(nights)
    54	                .map(room::priceOfNight)
    55	                .reduce(Money.ZERO, BigDecimal::add);
    56	        BigDecimal discount = ratePlan.discount(subtotal);
    57	        BigDecimal total = Money.round(subtotal.subtract(discount));
    58	        return new Reservation(null, room.number(), guestName, guestEmail, guestCpf, checkIn, checkOut,
    59	                guests, ratePlan, nights, subtotal, discount, total,
    60	                ReservationStatus.PENDING, Money.ZERO, null);
    61	    }
    62	
    63	    public void confirm() {
    64	        status = status.confirm();
    65	        amountPaid = total;
    66	    }
    67	
    68	    public void registerCheckIn() {
    69	        status = status.checkIn();
    70	    }
    71	
    72	    public void registerCheckOut() {
    73	        status = status.checkOut();
    74	    }
    75	
    76	    public void cancel() {
    77	        status = status.cancel();
    78	        refund = ratePlan.refund(amountPaid);
    79	    }
    80	
    81	    /** O que ficou com a pousada: o que foi pago menos o que foi devolvido. */
    82	    public BigDecimal retained() {
    83	        return refund == null ? amountPaid : Money.round(amountPaid.subtract(refund));
    84	    }
    85	
    86	    public boolean isPaid() {
    87	        return status.isPaid();
    88	    }
    89	
    90	    /** Ocupa a noite que começa em {@code night}: quem entra conta, quem sai no dia não. */
    91	    public boolean occupies(LocalDate night) {
    92	        return !night.isBefore(checkIn) && night.isBefore(checkOut);
    93	    }
    94	
    95	    public boolean overlaps(LocalDate otherCheckIn, LocalDate otherCheckOut) {
    96	        return checkIn.isBefore(otherCheckOut) && otherCheckIn.isBefore(checkOut);
    97	    }
    98	
    99	    public Long id() { return id; }
   100	    public void assignId(long id) { this.id = id; }
   101	    public int roomNumber() { return roomNumber; }
   102	    public String guestName() { return guestName; }
   103	    public String guestEmail() { return guestEmail; }
   104	    public String guestCpf() { return guestCpf; }
   105	    public LocalDate checkIn() { return checkIn; }
   106	    public LocalDate checkOut() { return checkOut; }
