   108	    public RatePlan ratePlan() { return ratePlan; }
   109	    public int nights() { return nights; }
   110	    public BigDecimal subtotal() { return subtotal; }
   111	    public BigDecimal discount() { return discount; }
   112	    public BigDecimal total() { return total; }
