     1	package br.com.mare.domain;
     2	
     3	import br.com.mare.persistence.JdbcMessageRepository;
     4	import br.com.mare.persistence.JdbcReservationRepository;
     5	
     6	import java.time.LocalDate;
     7	import java.util.function.Consumer;
     8	
     9	public class ReservationService {
    10	    private final JdbcReservationRepository reservations;
    11	    private final JdbcMessageRepository messages;
    12	
    13	    public ReservationService(JdbcReservationRepository reservations, JdbcMessageRepository messages) {
    14	        this.reservations = reservations;
    15	        this.messages = messages;
    16	    }
    17	
    18	    /** Dados já validados em formato (campos presentes, datas válidas, saída depois da entrada, ao menos 1 hóspede). */
    19	    public synchronized Reservation create(int roomNumber, String guestName, String guestEmail, String guestCpf,
    20	                                           LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    21	        Room room = Hotel.requireRoom(roomNumber);
    22	        if (guests > room.capacity()) {
    23	            throw new BusinessException(ErrorCode.CAPACITY_EXCEEDED,
    24	                    "O quarto " + roomNumber + " comporta no máximo " + room.capacity() + " hóspedes");
    25	        }
    26	        boolean taken = reservations.findActiveByRoom(roomNumber).stream()
    27	                .anyMatch(r -> r.overlaps(checkIn, checkOut));
    28	        if (taken) {
    29	            throw new BusinessException(ErrorCode.ROOM_UNAVAILABLE,
    30	                    "O quarto " + roomNumber + " já está reservado em alguma das noites");
    31	        }
    32	        Reservation reservation = Reservation.book(room, guestName, guestEmail, guestCpf,
    33	                checkIn, checkOut, guests, ratePlan);
    34	        reservations.insert(reservation);
    35	        return reservation;
    36	    }
    37	
    38	    public Reservation find(String id) {
    39	        long parsed;
    40	        try {
    41	            parsed = Long.parseLong(id);
    42	        } catch (NumberFormatException e) {
    43	            throw notFound(id);
    44	        }
    45	        return reservations.findById(parsed).orElseThrow(() -> notFound(id));
    46	    }
    47	
    48	    public synchronized Reservation confirm(String id) {
    49	        Reservation reservation = change(id, Reservation::confirm);
    50	        messages.add(Message.reservationConfirmed(reservation, receiptOf(reservation)));
    51	        return reservation;
    52	    }
    53	
    54	    public synchronized Reservation cancel(String id) {
    55	        return change(id, Reservation::cancel);
    56	    }
    57	
    58	    public synchronized Reservation checkIn(String id) {
    59	        return change(id, Reservation::registerCheckIn);
    60	    }
    61	
    62	    public synchronized Receipt checkOut(String id) {
    63	        return receiptOf(change(id, Reservation::registerCheckOut));
    64	    }
    65	
    66	    /** Segunda via: só existe para reserva paga. */
    67	    public Receipt document(String id) {
    68	        Reservation reservation = find(id);
    69	        if (!reservation.isPaid()) {
    70	            throw new BusinessException(ErrorCode.OPERATION_NOT_ALLOWED,
    71	                    "Reserva " + reservation.status() + " não tem comprovante");
    72	        }
    73	        return receiptOf(reservation);
    74	    }
    75	
    76	    private Reservation change(String id, Consumer<Reservation> operation) {
    77	        Reservation reservation = find(id);
    78	        operation.accept(reservation);
    79	        reservations.update(reservation);
    80	        return reservation;
    81	    }
    82	
    83	    private Receipt receiptOf(Reservation reservation) {
    84	        return Receipt.of(reservation, Hotel.requireRoom(reservation.roomNumber()));
    85	    }
    86	
    87	    private BusinessException notFound(String id) {
    88	        return new BusinessException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva " + id + " não existe");
    89	    }
    90	}
