    14	        this.reservations = reservations;
    15	        this.messages = messages;
    16	    }
    17	
    18	    /** Dados já validados em formato (campos presentes, datas válidas, saída depois da entrada, ao menos 1 hóspede). */
    19	    public synchronized Reservation create(int roomNumber, String guestName, String guestEmail, String guestCpf,
    20	                                           LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    21	        Room room = Hotel.requireRoom(roomNumber);
    22	        if (guests > room.capacity()) {
    23	            throw new BusinessException(ErrorCode.CAPACITY_EXCEEDED,
    24	                    "O quarto " + roomNumber + " comporta no máximo " + room.capacity() + " hóspedes");
    25	        }
    26	        boolean taken = reservations.findActiveByRoom(roomNumber).stream()
    27	                .anyMatch(r -> r.overlaps(checkIn, checkOut));
    28	        if (taken) {
    29	            throw new BusinessException(ErrorCode.ROOM_UNAVAILABLE,
    30	                    "O quarto " + roomNumber + " já está reservado em alguma das noites");
    31	        }
    32	        Reservation reservation = Reservation.book(room, guestName, guestEmail, guestCpf,
    33	                checkIn, checkOut, guests, ratePlan);
    34	        reservations.insert(reservation);
    35	        return reservation;
    36	    }
    37	
    38	    public Reservation find(String id) {
    39	        long parsed;
    40	        try {
    41	            parsed = Long.parseLong(id);
    42	        } catch (NumberFormatException e) {
    43	            throw notFound(id);
    44	        }
    45	        return reservations.findById(parsed).orElseThrow(() -> notFound(id));
    46	    }
    47	
    48	    public synchronized Reservation confirm(String id) {
    49	        Reservation reservation = change(id, Reservation::confirm);
    50	        messages.add(Message.reservationConfirmed(reservation, receiptOf(reservation)));
