    12	/** Conexão com o banco e criação do que o sistema precisa nele. */
    13	public final class Database {
    14	    private static final int ATTEMPTS = 30;
    15	
    16	    private Database() {
    17	    }
    18	
    19	    public static DataSource connect(String url, String user, String password) {
    20	        HikariConfig config = new HikariConfig();
    21	        config.setJdbcUrl(url);
    22	        if (user != null) {
    23	            config.setUsername(user);
    24	        }
    25	        if (password != null) {
    26	            config.setPassword(password);
    27	        }
    28	        config.setInitializationFailTimeout(-1);
    29	        HikariDataSource dataSource = new HikariDataSource(config);
    30	        createSchema(dataSource);
    31	        return dataSource;
    32	    }
    33	
    34	    static void createSchema(DataSource dataSource) {
    35	        SQLException last = null;
    36	        for (int attempt = 0; attempt < ATTEMPTS; attempt++) {
    37	            try (Connection c = dataSource.getConnection(); Statement s = c.createStatement()) {
    38	                s.execute("""
    39	                        CREATE TABLE IF NOT EXISTS reservations (
    40	                            id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    41	                            room_number INT NOT NULL,
    42	                            guest_name VARCHAR(255) NOT NULL,
    43	                            guest_email VARCHAR(255) NOT NULL,
    44	                            guest_cpf VARCHAR(50) NOT NULL,
    45	                            check_in DATE NOT NULL,
    46	                            check_out DATE NOT NULL,
    47	                            guests INT NOT NULL,
    48	                            rate_plan VARCHAR(30) NOT NULL,
    49	                            nights INT NOT NULL,
    50	                            subtotal NUMERIC(12,2) NOT NULL,
    51	                            discount NUMERIC(12,2) NOT NULL,
    52	                            total NUMERIC(12,2) NOT NULL,
    53	                            status VARCHAR(30) NOT NULL,
    54	                            amount_paid NUMERIC(12,2) NOT NULL,
    55	                            refund NUMERIC(12,2)
    56	                        )""");
    57	                s.execute("""
    58	                        CREATE TABLE IF NOT EXISTS messages (
    59	                            id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    60	                            channel VARCHAR(30) NOT NULL,
    61	                            recipient VARCHAR(255) NOT NULL,
    62	                            subject VARCHAR(255) NOT NULL,
    63	                            body TEXT NOT NULL
    64	                        )""");
    65	                return;
    66	            } catch (SQLException e) {
    67	                last = e;
    68	                try {
    69	                    Thread.sleep(1000);
    70	                } catch (InterruptedException ie) {
    71	                    Thread.currentThread().interrupt();
    72	                    break;
    73	                }
    74	            }
    75	        }
    76	        throw new IllegalStateException("Não foi possível preparar o banco", last);
