    24	    public Message add(Message m) {
    25	        String sql = "INSERT INTO messages (channel, recipient, subject, body) VALUES (?,?,?,?)";
    26	        try (Connection c = dataSource.getConnection();
    27	             PreparedStatement ps = c.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
    28	            ps.setString(1, m.channel().name());
    29	            ps.setString(2, m.to());
    30	            ps.setString(3, m.subject());
    31	            ps.setString(4, m.body());
    32	            ps.executeUpdate();
    33	            try (ResultSet keys = ps.getGeneratedKeys()) {
    34	                keys.next();
    35	                return new Message(keys.getLong("id"), m.channel(), m.to(), m.subject(), m.body());
    36	            }
    37	        } catch (SQLException e) {
    38	            throw new IllegalStateException(e);
    39	        }
    40	    }
