    46	            List<Message> result = new ArrayList<>();
    47	            while (rs.next()) {
    48	                result.add(new Message(rs.getLong("id"), Channel.valueOf(rs.getString("channel")),
    49	                        rs.getString("recipient"), rs.getString("subject"), rs.getString("body")));
    50	            }
    51	            return result;
