    24	        return reservations.findAll().stream()
    25	                .filter(Reservation::isPaid)
    26	                .filter(r -> r.occupies(night))
    27	                .sorted(Comparator.comparingInt(Reservation::roomNumber))
    28	                .toList();
    29	    }
