    11	
    12	/** Valida o corpo do POST /reservations. */
    13	final class RequestParser {
    14	    record NewReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
    15	                          LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    16	    }
    17	
    18	    private final JsonNode json;
    19	
    20	    private RequestParser(JsonNode json) {
    21	        this.json = json;
    22	    }
    23	
    24	    static NewReservation parse(ObjectMapper mapper, String body) {
    25	        JsonNode root;
    26	        try {
    27	            root = mapper.readTree(body);
    28	        } catch (Exception e) {
    29	            throw invalid("O corpo deve ser um JSON válido");
    30	        }
    31	        if (root == null || !root.isObject()) {
    32	            throw invalid("O corpo deve ser um objeto JSON");
    33	        }
    34	        RequestParser p = new RequestParser(root);
    35	        NewReservation r = new NewReservation(
    36	                p.integer("roomNumber"), p.text("guestName"), p.text("guestEmail"), p.text("guestCpf"),
    37	                p.date("checkIn"), p.date("checkOut"), p.integer("guests"), p.ratePlan());
    38	        if (!r.checkOut().isAfter(r.checkIn())) {
    39	            throw invalid("checkOut deve ser depois de checkIn");
    40	        }
    41	        if (r.guests() < 1) {
    42	            throw invalid("guests deve ser pelo menos 1");
    43	        }
    44	        return r;
    45	    }
    46	
    47	    private String text(String field) {
    48	        JsonNode node = json.get(field);
    49	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    50	            throw invalid("Campo obrigatório ausente ou inválido: " + field);
    51	        }
    52	        return node.asText();
    53	    }
    54	
    55	    private int integer(String field) {
    56	        JsonNode node = json.get(field);
    57	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
    58	            throw invalid("Campo obrigatório ausente ou inválido: " + field);
    59	        }
    60	        return node.asInt();
    61	    }
    62	
    63	    private LocalDate date(String field) {
    64	        try {
    65	            return LocalDate.parse(text(field));
    66	        } catch (DateTimeParseException e) {
    67	            throw invalid(field + " deve estar no formato 2027-07-10");
    68	        }
    69	    }
    70	
    71	    private RatePlan ratePlan() {
    72	        try {
    73	            return RatePlan.valueOf(text("ratePlan"));
    74	        } catch (IllegalArgumentException e) {
    75	            throw invalid("ratePlan deve ser STANDARD ou NON_REFUNDABLE");
    76	        }
    77	    }
    78	
    79	    private static BusinessException invalid(String message) {
    80	        return new BusinessException(ErrorCode.INVALID_REQUEST, message);
    81	    }
