   133	        assertEquals("""
   134	                Pousada Maré Alta,tourism-tax,2027-07
   135	                reservation,room,check_in,check_out,guests,nights,tax
   136	                1,101,2027-07-10,2027-07-13,2,3,27.00
   137	                total,27.00
   138	                """, call("GET", "/reports/tourism-tax?month=2027-07", null).body());
   139	        assertEquals("""
   140	                Pousada Maré Alta,rate-plans,2027-07
   141	                rate_plan,reservations,amount
